# Source for q/ae-calc-views3.js: Measurements (calculation practice) + Echo views (recognition) + Stress echo (numbers).
M="Measurements"; V="Echo views"; S="Stress echo"
Q=[
# --- Volumes, function, output ---
(M,"LVOT diameter 2.0 cm and LVOT VTI 25 cm. What is the stroke volume?","About 79 mL",["About 50 mL","About 157 mL","About 25 mL"],"Area = 0.785 × 2.0² = 3.14 cm². SV = 3.14 × 25 ≈ 79 mL.","C"),
(M,"Stroke volume 70 mL and heart rate 60 bpm. What is the cardiac output?","4.2 L/min",["7.0 L/min","0.42 L/min","42 L/min"],"CO = 70 mL × 60 = 4,200 mL/min.","F"),
(M,"EDV 150 mL and ESV 90 mL. What is the EF?","40%",["60%","90%","25%"],"EF = (150 − 90) ÷ 150 = 40%.","F"),
(M,"EDV 100 mL and ESV 40 mL. What are the stroke volume and EF?","SV 60 mL and EF 60%",["SV 40 mL and EF 40%","SV 140 mL and EF 100%","SV 60 mL and EF 40%"],"SV = EDV − ESV; EF = SV ÷ EDV.","F"),
(M,"LVIDd 60 mm and LVIDs 50 mm. What is the fractional shortening?","About 17%",["About 50%","About 83%","About 10%"],"(60 − 50) ÷ 60 ≈ 16.7%, which is reduced (normal about 25–45%).","F"),
(M,"Stroke volume 60 mL and BSA 2.0 m². The stroke volume index is:","30 mL/m², which is low flow",["120 mL/m²","60 mL/m²","3.0 mL/m²"],"Under 35 mL/m² is considered low flow.","F"),
(M,"Cardiac output 4.0 L/min and BSA 2.0 m². The cardiac index is:","2.0 L/min/m², which is low",["8.0 L/min/m²","4.0 L/min/m²","0.5 L/min/m²"],"Normal is about 2.5 to 4.0 L/min/m².","F"),
(M,"RVOT diameter 2.4 cm and RVOT VTI 15 cm. RV stroke volume is about:","68 mL",["36 mL","100 mL","15 mL"],"Area = 0.785 × 2.4² ≈ 4.52 cm². 4.52 × 15 ≈ 68 mL.","C"),
(M,"RV stroke volume 120 mL and LV stroke volume 60 mL. Qp/Qs is:","2.0",["0.5","1.0","60"],"A Qp/Qs of 2.0 means a large left-to-right shunt.","F"),
# --- Valve calculations ---
(M,"LVOT diameter 2.0 cm, LVOT VTI 20 cm, aortic valve VTI 80 cm. The AVA is about:","0.8 cm²",["1.6 cm²","3.1 cm²","0.25 cm²"],"AVA = 3.14 × 20 ÷ 80 ≈ 0.79 cm².","F"),
(M,"LVOT peak velocity 1.0 m/s and aortic peak velocity 4.0 m/s. The DVI is:","0.25",["4.0","0.5","1.0"],"A DVI of 0.25 or less suggests severe AS.","F"),
(M,"Mitral PHT 220 ms. The estimated mitral valve area is:","1.0 cm²",["2.2 cm²","0.5 cm²","1.5 cm²"],"MVA = 220 ÷ PHT.","F"),
(M,"LVOT stroke volume 60 mL and mitral stenosis VTI 60 cm. Mitral valve area by continuity is:","1.0 cm²",["0.5 cm²","2.0 cm²","3.6 cm²"],"MVA = SV ÷ mitral VTI (valid without significant MR or AR).","C"),
(M,"PISA radius 0.8 cm, aliasing velocity 40 cm/s, MR peak velocity 500 cm/s. EROA is about:","0.32 cm²",["0.64 cm²","0.16 cm²","1.0 cm²"],"Flow = 2π × 0.64 × 40 ≈ 161 mL/s. EROA = 161 ÷ 500 ≈ 0.32 cm².","C"),
(M,"EROA 0.32 cm² and MR VTI 160 cm. The regurgitant volume is about:","51 mL",["160 mL","32 mL","5 mL"],"RVol = EROA × VTI = 0.32 × 160 ≈ 51 mL.","C"),
(M,"Mitral inflow stroke volume 100 mL and LVOT stroke volume 60 mL. The MR regurgitant fraction is:","40%",["60%","160%","25%"],"RVol = 40 mL. RF = 40 ÷ 100 = 40%.","C"),
(M,"A peak velocity of 2 m/s corresponds to a peak gradient of:","16 mmHg",["4 mmHg","8 mmHg","32 mmHg"],"4 × 2² = 16 mmHg.","F"),
(M,"A peak gradient of 100 mmHg corresponds to a velocity of:","5 m/s",["10 m/s","25 m/s","2.5 m/s"],"√(100 ÷ 4) = 5 m/s.","F"),
(M,"Coarctation: proximal velocity 1.5 m/s and peak velocity 3.0 m/s. The expanded Bernoulli gradient is:","27 mmHg",["36 mmHg","9 mmHg","45 mmHg"],"4 × (9 − 2.25) = 27 mmHg. The simplified equation would give 36 mmHg.","C"),
# --- Pressures ---
(M,"TR peak velocity 3.0 m/s and RA pressure 3 mmHg. RVSP is:","39 mmHg",["36 mmHg","12 mmHg","45 mmHg"],"4 × 9 + 3 = 39 mmHg.","F"),
(M,"RVSP is 70 mmHg and the pulmonic valve peak gradient is 40 mmHg. PA systolic pressure is about:","30 mmHg",["70 mmHg","110 mmHg","40 mmHg"],"With PS, PASP = RVSP − PS gradient.","C"),
(M,"PR end-diastolic velocity 1.5 m/s and RA pressure 10 mmHg. PA diastolic pressure is:","19 mmHg",["9 mmHg","25 mmHg","15 mmHg"],"4 × 1.5² = 9; 9 + 10 = 19 mmHg.","C"),
(M,"Systolic BP 100 mmHg and MR peak velocity 4.5 m/s. Estimated LA pressure is:","19 mmHg",["81 mmHg","55 mmHg","4 mmHg"],"100 − 4 × 4.5² = 100 − 81 = 19 mmHg.","C"),
(M,"Diastolic BP 60 mmHg and AR end-diastolic velocity 3 m/s. Estimated LVEDP is:","24 mmHg",["36 mmHg","60 mmHg","6 mmHg"],"60 − 4 × 9 = 24 mmHg, which is raised.","C"),
(M,"PASP is 40 mmHg. Using the formula mean PAP ≈ 0.61 × PASP + 2, the mean PA pressure is about:","26 mmHg",["40 mmHg","14 mmHg","62 mmHg"],"0.61 × 40 + 2 ≈ 26 mmHg, above the 20 mmHg PH threshold.","C"),
(M,"TR velocity 3.0 m/s and RVOT VTI 15 cm. Using PVR ≈ (TRV ÷ VTI) × 10 + 0.16, PVR is about:","2.2 Wood units",["0.2 Wood units","20 Wood units","45 Wood units"],"3.0 ÷ 15 = 0.2; × 10 = 2; + 0.16 ≈ 2.2 WU.","C"),
(M,"IVC 1.5 cm that collapses less than 50% with sniff gives an estimated RA pressure of:","8 mmHg (intermediate)",["3 mmHg","15 mmHg","0 mmHg"],"Only a small IVC with more than 50% collapse gives 3 mmHg.","C"),
(M,"IVC 2.3 cm that collapses more than 50% with sniff gives an estimated RA pressure of:","8 mmHg (intermediate)",["3 mmHg","15 mmHg","20 mmHg"],"A large IVC with less than 50% collapse gives 15 mmHg.","C"),
# --- Diastology and indexes ---
(M,"Mitral E 90 cm/s and average e′ 6 cm/s. The average E/e′ is:","15",["5.4","96","1.5"],"Over 14 suggests raised filling pressure.","F"),
(M,"Mitral E 50 cm/s and A 80 cm/s in a 70-year-old. E/A is about 0.6, which suggests:","Impaired relaxation (often normal for age)",["Restrictive filling","Pseudonormal filling","Severe MR"],"E/A under 0.8 with a small E suggests normal LA pressure.","F"),
(M,"LA volume 68 mL and BSA 2.0 m². The LAVI is:","34 mL/m², at the upper limit of normal",["136 mL/m²","17 mL/m²","68 mL/m²"],"Over 34 mL/m² is considered enlarged.","F"),
(M,"Posterior wall 1.3 cm and LVIDd 4.4 cm. The relative wall thickness is about:","0.59, suggesting concentric geometry",["0.30, suggesting eccentric geometry","1.3","5.7"],"RWT = 2 × PWd ÷ LVIDd. Over 0.42 is increased.","C"),
(M,"MR jet rises from 1 to 3 m/s in 40 ms. LV dP/dt is:","800 mmHg/s",["1,200 mmHg/s","32 mmHg/s","4,000 mmHg/s"],"32 ÷ 0.040 = 800 mmHg/s, reduced (normal over 1,200).","C"),
(M,"IVCT 50 ms, IVRT 70 ms and ejection time 300 ms. The Tei index is:","0.40",["0.17","2.5","4.2"],"(50 + 70) ÷ 300 = 0.40.","C"),
(M,"Six segments score 3 (akinetic) and the remaining eleven score 1. The WMSI is about:","1.71",["3.0","1.0","2.5"],"(18 + 11) ÷ 17 ≈ 1.71.","C"),
(M,"A TAPSE of 12 mm means:","Reduced RV longitudinal function",["Normal RV function","Hyperdynamic RV","LV dysfunction only"],"TAPSE under 17 mm is abnormal.","F"),
(M,"AR jet width 7 mm and LVOT width 20 mm. The jet width ratio is:","35%, consistent with moderate AR",["65%, severe AR","10%, trace AR","Over 100%"],"65% or more suggests severe AR.","C"),
# --- View recognition ---
(V,"A view shows the RV at the top, the LV below it, the mitral and aortic valves, and the aorta running across the screen. This is the:","Parasternal long-axis view",["Apical four-chamber","Subcostal four-chamber","Suprasternal view"],"The descending aorta appears in cross section behind the LA.","F"),
(V,"A round view shows three aortic cusps in the center, with the RA on the left of the screen and the RVOT curving over the top. This is the:","PSAX view at the aortic valve level",["PSAX at the mitral level","Apical five-chamber","Subcostal short axis"],"The pulmonic valve is seen on the right of the screen.","F"),
(V,"A view shows the LV, mitral valve and LA with the LAA, but no RV and no aorta. This is the:","Apical two-chamber view",["Apical four-chamber view","Apical long-axis view","PLAX"],"It shows the inferior and anterior walls.","F"),
(V,"A view shows the aortic arch with its three branches and a round vessel underneath. This is the:","Suprasternal long-axis view",["Subcostal view","PSAX","Apical view"],"The round vessel is the right pulmonary artery.","F"),
(V,"A parasternal view shows the RVOT, pulmonic valve and main PA in long axis. It is obtained by:","Tilting the transducer up toward the left shoulder from PLAX",["Tilting down toward the right hip","Moving to the apex","Moving to the subcostal window"],"It is used for PR and PS Doppler.","F"),
(V,"In PSAX at the papillary level, the LV looks oval instead of round. The best fix is to:","Adjust rotation slightly until the LV is round",["Increase depth","Add contrast","Switch to M-mode"],"An oval LV means the plane is oblique.","F"),
(V,"Bowel gas blocks the subcostal view of the IVC. A useful approach is to:","Move slightly to the right and use the liver as a window, with a deep breath in",["Press as hard as possible","Use a higher frequency only","Skip the IVC every time"],"Inspiration moves the liver and heart downward.","F"),
(V,"The TEE mid-esophageal aortic valve long-axis view is obtained at about:","120° to 140°",["0°","45°","90°"],"It shows the LVOT, aortic valve and proximal ascending aorta.","C"),
(V,"The TEE transgastric basal short-axis view shows:","The mitral valve in short axis ('fish mouth')",["The aortic arch","The bicaval view","The pulmonary veins only"],"It is useful for locating mitral scallop pathology.","C"),
(V,"The TEE mid-esophageal RV inflow-outflow view (about 60° to 75°) shows:","The tricuspid valve, RVOT and pulmonic valve wrapped around the aortic valve",["Only the LAA","The mitral valve only","The descending aorta"],"It is useful for TR and pulmonic valve Doppler.","C"),
(V,"An apical view shows the LV, LA and the aortic valve with the LVOT, but no RV and no RA. This is the:","Apical long-axis (three-chamber) view",["Apical two-chamber view","Apical four-chamber view","Subcostal view"],"Rotate counterclockwise from A2C, or about 120° from A4C.","F"),
(V,"A subcostal short-axis view at the great vessel level is especially useful in:","Patients with poor parasternal windows",["Patients with excellent parasternal windows only","Measuring LV mass","Stress echo only"],"It can replace parasternal short-axis views when needed.","F"),
(V,"An apical four-chamber image shows the coronary sinus running across the bottom of the LA. This means the transducer is:","Tilted posteriorly",["Tilted anteriorly","Rotated 90°","Moved to the subcostal window"],"Anterior tilt brings in the LVOT (five-chamber view).","F"),
(V,"Which view best shows the RV free wall for strain and TAPSE?","RV-focused apical four-chamber view",["PLAX","Suprasternal","PSAX at the aortic level"],"Keep the RV apex in view and the RV maximized.","F"),
(V,"For left-sided Doppler in the apical view, the cursor should be:","As parallel as possible to the flow",["Perpendicular to the flow","At 90° to the valve","Away from the flow"],"Even small angles reduce measured velocity.","F"),
# --- Stress numbers ---
(S,"For a 60-year-old, 85% of age-predicted maximum heart rate is:","136 bpm",["160 bpm","120 bpm","153 bpm"],"(220 − 60) × 0.85 = 136 bpm.","F"),
(S,"For a 40-year-old, 85% of age-predicted maximum heart rate is:","153 bpm",["180 bpm","136 bpm","170 bpm"],"(220 − 40) × 0.85 = 153 bpm.","F"),
(S,"One MET is equal to an oxygen use of about:","3.5 mL O₂/kg/min",["35 mL O₂/kg/min","1 L O₂/min","0.5 mL O₂/kg/min"],"METs describe exercise workload.","C"),
(S,"An exercise capacity under about 5 METs suggests:","Poor functional capacity and higher risk",["Excellent fitness","Normal capacity for a young athlete","No meaning"],"More than 10 METs suggests a good prognosis.","C"),
(S,"Rate-pressure product (double product) at peak stress with HR 150 and systolic BP 180 is:","27,000",["330","2,700","150"],"HR × systolic BP; it reflects myocardial oxygen demand.","C"),
(S,"A 70 kg patient receives dobutamine at 20 mcg/kg/min. The dose is:","1,400 mcg/min (1.4 mg/min)",["20 mcg/min","140 mcg/min","14 mg/min"],"70 × 20 = 1,400 mcg/min.","C"),
(S,"A stress echo is usually called positive for ischemia when:","A new or worsening wall motion abnormality appears in at least two contiguous segments",["Heart rate rises","Blood pressure rises normally","The LV gets smaller"],"Single-segment changes are less reliable.","C"),
(S,"In a treadmill test, a patient reaches 145 bpm (88% of target) with no wall motion changes. The test is:","Adequate and negative for ischemia",["Inadequate","Positive","Not interpretable"],"85% or more of age-predicted maximum is adequate.","F"),
]
